def three_sum(nums):
    values = sorted(nums)
    n = len(values)
    found = []
    seen = set()
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if values[i] + values[j] + values[k] == 0:
                    key = (values[i], values[j], values[k])
                    if key not in seen:
                        seen.add(key)
                        found.append([values[i], values[j], values[k]])
    found.sort()
    return found
